import {ContractError,validDate} from './cloud-contract.mjs';
import {attendanceId,periodRecord} from './attendance-contract.mjs';
import {pagedRows} from './management-model.mjs';
export const exceptionKinds={late:'迟到',insufficient:'时长不足'};
export const exceptionOutcomes={confirmed:'核实属实',special:'特殊情况已说明',reopened:'重新待核实'};
export const exceptionStatuses={pending:'待核实',confirmed:'核实属实',special:'特殊情况已说明',stale:'原考勤变化，待复核','not-applicable':'当前无须核实'};
export const exceptionIssues={'legacy-field':'历史外勤不按工作室日常时间规则判断。','multiple-periods':'当天有重复工作段，请先核对补正。',incomplete:'上下班尚未完整，先核对漏卡，不直接认定时长不足。','invalid-times':'时间跨日、在未来或顺序异常，请先核对补正。'};
const version=v=>{if(!Number.isSafeInteger(v)||v<1)throw new ContractError('请重新读取原考勤。');return v;};
const stamp=v=>typeof v==='string'&&Number.isFinite(Date.parse(v));
function review(r){attendanceId(r.id);if(!Object.hasOwn(exceptionKinds,r.kind)||!Object.hasOwn(exceptionOutcomes,r.outcome)||typeof r.note!=='string'||!r.note.trim()||typeof r.actor_name!=='string'||!stamp(r.created_at)||!r.source_snapshot)throw new ContractError('核实历史不完整。');version(r.period_version);version(r.revision);return r;}
export function exceptionPage(v){pagedRows(v);if(v.limit!==50||v.rows.length>50||new Set(v.rows.map(r=>r.id)).size!==v.rows.length)throw new ContractError();for(const r of v.rows){attendanceId(r.periodId);version(r.periodVersion);if(!validDate(r.workDate)||!Object.hasOwn(exceptionKinds,r.kind)||!Object.hasOwn(exceptionStatuses,r.reviewStatus)||!stamp(r.effectiveIn)||!stamp(r.effectiveOut)||!Number.isSafeInteger(r.durationMinutes)||r.durationMinutes<0)throw new ContractError('时间异常清单不完整。');if(r.reviewId!==null)attendanceId(r.reviewId);}return v;}
export function exceptionDetail(v){if(!v||typeof v.eligible!=='boolean'||!(v.issue===null||Object.hasOwn(exceptionIssues,v.issue))||!Array.isArray(v.rows)||v.rows.length!==2||new Set(v.rows.map(r=>r.kind)).size!==2)throw new ContractError();periodRecord(v.period);for(const r of v.rows){if(!Object.hasOwn(exceptionKinds,r.kind)||typeof r.flag!=='boolean'||!Object.hasOwn(exceptionStatuses,r.reviewStatus))throw new ContractError();if(r.latest!==null)review(r.latest);}if(v.eligible&&(!v.metrics||!Number.isSafeInteger(v.metrics.durationMinutes)||typeof v.metrics.late!=='boolean'||typeof v.metrics.insufficient!=='boolean'))throw new ContractError();return v;}
export function exceptionHistory(v){pagedRows(v);if(v.limit!==50)throw new ContractError();v.rows.forEach(review);return v;}
export function exceptionPayload(v){const keys=['requestKey','expectedPeriodVersion','expectedReviewId','kind','outcome','note'];if(!v||keys.some(k=>!Object.hasOwn(v,k))||Object.keys(v).some(k=>!keys.includes(k))||!Object.hasOwn(exceptionKinds,v.kind)||!Object.hasOwn(exceptionOutcomes,v.outcome)||typeof v.note!=='string'||!v.note.trim()||v.note.trim().length>2000)throw new ContractError('请核对异常类型、核实结论和说明。');return {requestKey:attendanceId(v.requestKey),expectedPeriodVersion:version(v.expectedPeriodVersion),expectedReviewId:v.expectedReviewId===null?null:attendanceId(v.expectedReviewId),kind:v.kind,outcome:v.outcome,note:v.note.trim()};}
